/**
 * Rate applied to card transactions of the given KST settlement date.
 * A carried-over quote is not that day's rate, so the same date is re-queried from the settlement source.
 */
public BigDecimal settlementRate(String currency, LocalDate date) {
    FxQuote q = quote(currency, date);
    if (!q.lagged()) return q.rate();
    return settlementCache.computeIfAbsent(q.pair() + "@" + date, k -> {
        vendorCalls++;
        return FxqClient.parse(client.rate(q.pair(), date, SETTLEMENT_SOURCE));
    }).rate();
}

